import { request, requestBytes, requestPublic, describeServerError } from './client.js';
import { pathToModule, moduleToPath } from '../core/snapshot.js';

/**
 * Fetch the project-layout descriptor (GET /capabilities). Unauthenticated;
 * the result is returned unvalidated.
 */
export async function fetchCapabilities() {
  return requestPublic('GET', '/capabilities');
}

/**
 * Batch deploy (POST /deploy). `manifest` is the full module set: modules
 * absent from it are deleted. A null `expected_revision` makes the deploy
 * unconditional.
 * @returns {Promise<{ revision: number, canonical_modules: Object<string,string>, db_changes?: any[] }>}
 */
export async function batchDeploy(token, { expected_revision, manifest, changed_sources, static: staticSection }) {
  // An absent section (`manifest` or `static`) leaves that part untouched.
  const body = {};
  if (manifest !== undefined) {
    body.manifest = manifest;
    body.changed_sources = changed_sources || {};
  }
  if (staticSection !== undefined) body.static = staticSection;
  if (expected_revision != null) body.expected_revision = expected_revision;
  return request('POST', '/deploy', token, body);
}

/**
 * Declare a static version (POST /static/prepare) from the file manifest
 * `{ path: { hash, size } }` and the serving config.
 * Returns { hash, missing, expires_at }; `missing` lists the blob hashes to upload.
 */
export async function prepareStatic(token, manifest, config) {
  return request('POST', '/static/prepare', token, { manifest, config });
}

/** Upload one static blob as raw bytes, bound to the prepared bundle. */
export async function uploadBlob(token, hash, bundle, bytes) {
  return requestBytes('PUT', `/static/blob/${hash}?bundle=${bundle}`, token, bytes);
}

/**
 * Run a module on the server without deploying (POST /run). `sources` is the
 * full module space `{ moduleName: code }` and must contain `moduleName`;
 * the deployed state is not consulted.
 */
export async function runFunction(token, moduleName, sources, args, ctx) {
  return request('POST', '/run', token, {
    module: moduleName,
    sources,
    args,
    ctx: ctx || {},
  });
}

/** Full server state (GET /get): { revision, canonical_modules, static? }. */
export async function getFiles(token) {
  return request('GET', '/get', token);
}

/**
 * Webhook status (GET /webhook): the live webhook, the `expected` one for the
 * deployed handlers, and the `in_sync` verdict.
 * @returns {Promise<{ url:string, allowed_updates:string[], pending_update_count:number,
 *   last_error_date?:number, last_error_message?:string,
 *   expected:{ url:string, allowed_updates:string[] }, in_sync:boolean }>}
 */
export async function getWebhook(token) {
  return request('GET', '/webhook', token);
}

/**
 * Re-point the webhook and allowed_updates to the deployed handlers
 * (POST /webhook/sync). Returns the getWebhook shape.
 */
export async function syncWebhook(token, { drop_pending = false } = {}) {
  const body = {};
  if (drop_pending) body.drop_pending_updates = true;
  return request('POST', '/webhook/sync', token, body);
}

/** Pending DB changes for the deployed schema (GET /migrate): { db_changes }. */
export async function getMigrationStatus(token) {
  return request('GET', '/migrate', token);
}

/**
 * Compute or apply a migration (POST /migrate).
 *   apply:   change ids to apply (see changeId() in db-changes.js)
 *   schema:  diff against this schema source instead of the deployed one;
 *            the deployed schema is not updated
 *   dry_run: return db_changes only; `apply` is ignored
 */
export async function applyMigration(token, { apply, schema, dry_run = false } = {}) {
  const body = {};
  if (apply != null) body.apply = apply;
  if (schema != null) body.schema = schema;
  if (dry_run) body.dry_run = true;
  return request('POST', '/migrate', token, body);
}

export { pathToModule, moduleToPath, describeServerError };
